import type * as Either from "../Either.js";
import type { Option } from "../Option.js";
export declare const TypeId: Either.TypeId;
export declare const isEither: (input: unknown) => input is Either.Either<unknown, unknown>;
export declare const isLeft: <R, L>(ma: Either.Either<R, L>) => ma is Either.Left<L, R>;
export declare const isRight: <R, L>(ma: Either.Either<R, L>) => ma is Either.Right<L, R>;
export declare const left: <L>(left: L) => Either.Either<never, L>;
export declare const right: <R>(right: R) => Either.Either<R>;
export declare const getLeft: <R, L>(self: Either.Either<R, L>) => Option<L>;
export declare const getRight: <R, L>(self: Either.Either<R, L>) => Option<R>;
export declare const fromOption: {
    <L>(onNone: () => L): <R>(self: Option<R>) => Either.Either<R, L>;
    <R, L>(self: Option<R>, onNone: () => L): Either.Either<R, L>;
};
